pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        address originalOwner = c.owner();
        // Call setOwner – if it reverts, the catch block will handle it
        (bool success, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", _newOwner));
        // If call succeeds, then the owner might have changed; if it reverts, it stays the same.
        // The buggy version always reverts, so success will be false; the reference version may succeed (if called by owner).
        assertTrue(success ? c.owner() == _newOwner : c.owner() == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerBefore;

    function setUp() public { 
        c = new C(); 
        ownerBefore = c.owner();
    }

    function testFuzz_property(address newOwner) public {
        // Restrict: newOwner must not be owner (otherwise the call would succeed in reference)
        vm.assume(newOwner != ownerBefore);

        // Try to set owner as someone other than current owner
        address caller = address(0x1234);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeCall(c.setOwner, (newOwner)));

        // After call, if it succeeded, owner should be caller (msg.sender) since onlyOwner doesn't check properly
        // In reference: onlyOwner checks msg.sender == owner, so call reverts and owner stays
        // In mutant: require(false) always reverts, so call never succeeds
        // But the property is: owner must always be either ownerBefore (if call reverted) or caller (if call succeeded)
        assertTrue(success ? c.owner() == caller : c.owner() == ownerBefore);
    }
}

