pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Try to setOwner from the current owner
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        (bool success, ) = address(c).call(abi.encodeCall(c.setOwner, (newOwner)));
        // After the call, owner should be newOwner if successful
        assertTrue(success ? c.owner() == newOwner : true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address prevOwner = c.owner();
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == prevOwner);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address originalOwner = c.owner();
        vm.assume(newOwner != address(0) && newOwner != originalOwner);

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted == true || c.owner() == originalOwner);
    }
}
